	flLine(wd, ln, et, port.TextBlob("12.50"), 1, 30000, 7300, 38000, 8300, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Ink"), 1, 7200, 8600, 15000, 9600, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("7.00"), 1, 30000, 8600, 38000, 9600, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Item"), 2, 7200, 6000, 15000, 7000, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Amount"), 2, 30000, 6000, 38000, 7000, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Glue"), 2, 7200, 7300, 15000, 8300, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("3.10"), 2, 30000, 7300, 38000, 8300, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Tape"), 2, 7200, 8600, 15000, 9600, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("4.20"), 2, 30000, 8600, 38000, 9600, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Item"), 3, 7200, 6000, 15000, 7000, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Amount"), 3, 30000, 6000, 38000, 7000, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Cups"), 3, 7200, 7300, 15000, 8300, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("8.80"), 3, 30000, 7300, 38000, 8300, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("Mugs"), 3, 7200, 8600, 15000, 9600, 0, 1000)
	flLine(wd, ln, et, port.TextBlob("6.40"), 3, 30000, 8600, 38000, 9600, 0, 1000)
