	// Even pages say the book's title (the body's heading too: dropped), odd pages the chapter (kept), page numbers at the foot
	// of every page but the first.
	flPages(wd, ln, et, 5)
	flLine(wd, ln, et, port.TextBlob("The Handbook"), 1, 7200, 8000, 30000, 9500, 0, 1800)
